    with open(path,"r",encoding="utf-8",errors="replace") as fh: return fh.read()

def get_role(raw):
    m = re.search(r'"evidence_role"\s*:\s*"([a-z_]+)"', raw)
    if m: return m.group(1)
    for r in ROLES:
        if re.search(r'[Ee]vidence[ _]?[Rr]ole[^A-Za-z]{0,6}'+re.escape(r), raw):
            return r
    return None

def get_body(raw, ext):
    if ext == ".json":
        m = re.search(r'"body"\s*:\s*"(.*?)"\s*,', raw, re.S)
        if m: return m.group(1)
    if ext == ".csv":
        # find body row
        for line in raw.splitlines():
            if ',body,' in line:
                # value may be quoted
                m = re.search(r',body,"(.*)"$', line)
                if m: return m.group(1)
        return None
    if ext == ".md":
        # first blockquote line after control table
        m = re.search(r'>\s*(.{10,})', raw)
        if m: return m.group(1)
