        lines = raw.splitlines()
        for i,l in enumerate(lines):
            if l.strip()=="NATIVE RECORD" and i+1<len(lines):
                return lines[i+1].strip()
    if ext == ".eml":
        # first non-empty body line after blank line following headers
        parts = raw.split("\n\n",1)
        if len(parts)>1:
            for line in parts[1].splitlines():
                s=line.strip()
                if s and not s.startswith("SOURCE") and not s.startswith("-----"):
